export const GLOSSARY = [{"term":"browser","aliases":["web browser","chrome"],"en":"The app you use to open websites, like Chrome. It shows you web pages when you type an address or tap a link.","hi":"वह ऐप जिससे आप वेबसाइट खोलते हैं, जैसे Chrome। पता टाइप करने या लिंक पर टैप करने पर यह वेब पेज दिखाता है।"},{"term":"browser tab","aliases":["tab","tabs"],"en":"One open page inside your browser. You can have many tabs open at once and switch between them, like pages in a notebook.","hi":"आपके ब्राउज़र में खुला एक पेज। आप एक साथ कई टैब खोल सकते हैं और उनके बीच बदल सकते हैं, जैसे कॉपी के पन्ने।"},{"term":"link","aliases":["url","web address","hyperlink"],"en":"Text or a button you tap to go to another page. A web address (URL) looks like https://example.com.","hi":"ऐसा टेक्स्ट या बटन जिस पर टैप करने से दूसरा पेज खुलता है। वेब पता (URL) ऐसा दिखता है: https://example.com।"},{"term":"file","aliases":["files","document"],"en":"A saved item on your phone or computer: a photo, a PDF, a typed document, or a piece of code. Every file has a name and lives inside a folder.","hi":"आपके फ़ोन या कंप्यूटर में सहेजी गई कोई चीज़: फ़ोटो, PDF, टाइप किया दस्तावेज़ या कोड। हर फ़ाइल का एक नाम होता है और वह किसी फ़ोल्डर में रहती है।"},{"term":"folder","aliases":["directory","folders"],"en":"A container that holds files, like a paper folder holds sheets. Folders can be inside other folders.","hi":"फ़ाइलें रखने का डिब्बा, जैसे कागज़ का फ़ोल्डर पन्ने रखता है। फ़ोल्डर के अंदर और फ़ोल्डर हो सकते हैं।"},{"term":"account","aliases":["accounts","sign up","sign in","login","register"],"en":"Your personal space on a website or app. You create one with an email or phone number and a password, then sign in to use it.","hi":"किसी वेबसाइट या ऐप पर आपकी निजी जगह। ईमेल या फ़ोन नंबर और पासवर्ड से इसे बनाते हैं, फिर साइन इन करके उपयोग करते हैं।"},{"term":"password","aliases":["passwords"],"en":"A secret word or phrase that protects your account. Never share it. Use a different one for each important account.","hi":"एक गुप्त शब्द जो आपके खाते की रक्षा करता है। इसे किसी को न बताएं। हर ज़रूरी खाते के लिए अलग पासवर्ड रखें।"},{"term":"OTP","aliases":["one-time password","verification code"],"en":"A short code sent to your phone or email to prove it is really you. It works only once and only for a few minutes.","hi":"आपके फ़ोन या ईमेल पर भेजा गया छोटा कोड जो साबित करता है कि यह आप ही हैं। यह सिर्फ़ एक बार और कुछ मिनट तक चलता है।"},{"term":"download","aliases":["downloads","downloading"],"en":"Copying a file from the internet onto your device so you can open it later, even without internet.","hi":"इंटरनेट से कोई फ़ाइल अपने डिवाइस पर उतारना ताकि बाद में बिना इंटरनेट भी खोल सकें।"},{"term":"upload","aliases":["uploading"],"en":"Sending a file from your device to a website or app, for example attaching a photo or submitting your project.","hi":"अपने डिवाइस से कोई फ़ाइल वेबसाइट या ऐप पर भेजना, जैसे फ़ोटो लगाना या प्रोजेक्ट जमा करना।"},{"term":"install","aliases":["installing","installed"],"en":"Adding a new app or program to your device so you can run it. On a phone this happens through the Play Store.","hi":"अपने डिवाइस में नया ऐप या प्रोग्राम जोड़ना ताकि उसे चला सकें। फ़ोन पर यह Play Store से होता है।"},{"term":"app","aliases":["application","apps","software","program"],"en":"A program that does one job: WhatsApp for messages, a calculator for maths, a code editor for writing code.","hi":"एक प्रोग्राम जो एक काम करता है: संदेशों के लिए WhatsApp, गणित के लिए कैलकुलेटर, कोड लिखने के लिए कोड एडिटर।"},{"term":"spreadsheet","aliases":["excel","google sheets","sheet"],"en":"A grid of rows and columns for numbers and lists, like a register. Excel and Google Sheets are spreadsheet apps. Each box is a cell.","hi":"संख्याओं और सूचियों के लिए पंक्तियों और स्तंभों की जाली, जैसे रजिस्टर। Excel और Google Sheets स्प्रेडशीट ऐप हैं। हर खाना एक सेल है।"},{"term":"command","aliases":["command line","terminal","cli","shell","typed a command"],"en":"A typed instruction to the computer, written in a black text window called the terminal, instead of tapping buttons. Example: typing `ls` lists files.","hi":"कंप्यूटर को टाइप करके दिया गया निर्देश, बटन दबाने के बजाय टर्मिनल नाम की काली टेक्स्ट विंडो में। जैसे `ls` टाइप करने से फ़ाइलें दिखती हैं।"},{"term":"code","aliases":["coding","source code","programming"],"en":"Written instructions that tell a computer exactly what to do, in a language like Python or JavaScript.","hi":"लिखे हुए निर्देश जो कंप्यूटर को ठीक-ठीक बताते हैं कि क्या करना है, Python या JavaScript जैसी भाषा में।"},{"term":"bug","aliases":["debug","debugging","error"],"en":"A mistake in code that makes a program behave wrongly. Debugging means finding and fixing it.","hi":"कोड की गलती जिससे प्रोग्राम गलत चलता है। डीबगिंग का मतलब है उसे ढूंढना और ठीक करना।"},{"term":"editor","aliases":["code editor","text editor","vs code","ide"],"en":"An app for writing code, like a notebook made for programmers. VS Code is a common free one. On a phone, Replit or Acode work.","hi":"कोड लिखने का ऐप, प्रोग्रामरों की कॉपी जैसा। VS Code एक आम मुफ़्त एडिटर है। फ़ोन पर Replit या Acode चलते हैं।"},{"term":"Git","aliases":["repository","repo","github","version control","commit"],"en":"A tool that saves versions of your code so you can go back if something breaks. GitHub is a website that stores these saved projects (repositories) online.","hi":"एक टूल जो आपके कोड के संस्करण सहेजता है ताकि कुछ टूटे तो पीछे जा सकें। GitHub एक वेबसाइट है जो ये प्रोजेक्ट (रिपॉज़िटरी) ऑनलाइन रखती है।"},{"term":"cloud","aliases":["cloud computing","server","hosting"],"en":"Computers in a data centre that you rent over the internet instead of owning. A server is one such computer that answers requests from apps and websites.","hi":"डेटा सेंटर के कंप्यूटर जिन्हें आप खरीदने के बजाय इंटरनेट पर किराए पर लेते हैं। सर्वर ऐसा ही एक कंप्यूटर है जो ऐप और वेबसाइट की मांगों का जवाब देता है।"},{"term":"database","aliases":["sql","databases"],"en":"An organised store of information, like many linked spreadsheets, that apps read from and write to. SQL is the language for asking it questions.","hi":"जानकारी का व्यवस्थित भंडार, कई जुड़ी हुई स्प्रेडशीट जैसा, जिसे ऐप पढ़ते और लिखते हैं। SQL उससे सवाल पूछने की भाषा है।"},{"term":"API","aliases":["apis"],"en":"A doorway that lets one program ask another for data or actions, for example a weather app asking a weather service for today's forecast.","hi":"एक दरवाज़ा जिससे एक प्रोग्राम दूसरे से डेटा या काम मांगता है, जैसे मौसम ऐप मौसम सेवा से आज का पूर्वानुमान मांगता है।"},{"term":"framework","aliases":["library","libraries","frameworks","react"],"en":"Ready-made code written by others that you build on, so you do not start from zero. React and Django are examples.","hi":"दूसरों का बना-बनाया कोड जिस पर आप अपना काम बनाते हैं, ताकि शून्य से शुरू न करना पड़े। React और Django उदाहरण हैं।"},{"term":"open source","aliases":["open-source","free software"],"en":"Software whose code anyone can read, use and improve for free. Many of the best learning tools are open source.","hi":"ऐसा सॉफ़्टवेयर जिसका कोड कोई भी मुफ़्त पढ़, इस्तेमाल और सुधार सकता है। कई बेहतरीन सीखने के टूल ओपन सोर्स हैं।"},{"term":"project","aliases":["projects","capstone","checkpoint"],"en":"Something real you make to prove a skill: a web page, a spreadsheet report, a small program. Projects are evidence; watching videos alone is not.","hi":"कोई असली चीज़ जो आप स्किल साबित करने के लिए बनाते हैं: वेब पेज, स्प्रेडशीट रिपोर्ट, छोटा प्रोग्राम। प्रोजेक्ट सबूत हैं; सिर्फ़ वीडियो देखना नहीं।"},{"term":"portfolio","aliases":["portfolios"],"en":"A collection of your finished projects that you can show to a mentor or employer, usually as a web page or a GitHub profile.","hi":"आपके पूरे किए प्रोजेक्ट का संग्रह जिसे आप मेंटर या नियोक्ता को दिखा सकें, अक्सर एक वेब पेज या GitHub प्रोफ़ाइल के रूप में।"},{"term":"tier","aliases":["level","tiers"],"en":"Your current level in one subject: Intern/Newbie, Fresher, Developer or Master. You can be at different tiers in different subjects.","hi":"एक विषय में आपका मौजूदा स्तर: इंटर्न/नौसिखिया, फ्रेशर, डेवलपर या मास्टर। अलग विषयों में आपका स्तर अलग हो सकता है।"},{"term":"placement quiz","aliases":["quiz","placement"],"en":"A few short questions that check what you can already do, so your path starts at the right level rather than too easy or too hard.","hi":"कुछ छोटे सवाल जो जांचते हैं कि आप अभी क्या कर सकते हैं, ताकि आपका रास्ता सही स्तर से शुरू हो, न बहुत आसान न बहुत कठिन।"},{"term":"free-to-audit","aliases":["audit","free to audit"],"en":"You can watch and read everything for free, but a certificate or grading costs money. You do not need the certificate to learn.","hi":"आप सब कुछ मुफ़्त देख और पढ़ सकते हैं, पर सर्टिफ़िकेट या ग्रेडिंग के पैसे लगते हैं। सीखने के लिए सर्टिफ़िकेट ज़रूरी नहीं है।"},{"term":"freemium","aliases":[],"en":"Part of the content is free and part is paid. This app only sends you to the free part.","hi":"कुछ सामग्री मुफ़्त है और कुछ पैसों की। यह ऐप आपको सिर्फ़ मुफ़्त हिस्से में भेजता है।"},{"term":"free-with-account","aliases":["free with account"],"en":"Free to learn, but you must create an account (usually with an email) before you can start.","hi":"सीखना मुफ़्त है, पर शुरू करने से पहले खाता (आमतौर पर ईमेल से) बनाना होगा।"},{"term":"credential","aliases":["certificate","credentials"],"en":"A signed record that you completed a tier in this app. It proves your own work; it is not a college degree or a job guarantee.","hi":"एक हस्ताक्षरित रिकॉर्ड कि आपने इस ऐप में एक स्तर पूरा किया। यह आपके अपने काम का प्रमाण है; कॉलेज डिग्री या नौकरी की गारंटी नहीं।"},{"term":"screenshot","aliases":["screen shot"],"en":"A photo of what is on your screen right now. On most phones, press the power and volume-down buttons together.","hi":"आपकी स्क्रीन पर जो अभी दिख रहा है उसकी तस्वीर। ज़्यादातर फ़ोन पर पावर और वॉल्यूम-डाउन बटन साथ दबाएं।"},{"term":"wifi","aliases":["wi-fi","mobile data","internet connection","offline"],"en":"Your connection to the internet. Wi-Fi comes from a router at home or a library; mobile data comes from your SIM. Offline means no connection.","hi":"इंटरनेट से आपका जुड़ाव। Wi-Fi घर या लाइब्रेरी के राउटर से आता है; मोबाइल डेटा आपकी SIM से। ऑफ़लाइन का मतलब कोई कनेक्शन नहीं।"},{"term":"roadmap","aliases":["roadmap.sh","syllabus"],"en":"A map of topics in a subject, in the order people usually learn them. It shows what exists; it is not a course by itself.","hi":"किसी विषय के टॉपिक का नक्शा, उस क्रम में जिसमें लोग आमतौर पर सीखते हैं। यह बताता है क्या-क्या है; यह अपने आप में कोर्स नहीं है।"}];
